:root {
  --bg: #f3f6fb;
  --panel: #ffffff;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --muted: #64748b;
  --border: #dfe7f3;
  --danger: #dc2626;
  --danger-soft: #fee2e2;
  --text: #0f172a;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.page-shell {
  max-width: 1200px;
  margin: 0 auto;
  padding: 32px 20px 60px;
}

.topbar {
  margin-bottom: 24px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 12px;
  font-weight: 700;
}

h1 {
  margin: 8px 0 0;
  font-size: 2.2rem;
}

.layout {
  display: grid;
  grid-template-columns: minmax(280px, 360px) minmax(0, 1fr);
  gap: 24px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.03);
  padding: 24px;
}

form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-weight: 600;
}

input,
textarea,
select,
button {
  font: inherit;
}

input,
textarea,
select {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
  background: #fff;
}

textarea {
  resize: vertical;
}

.button-row,
.toolbar {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

button {
  border: none;
  border-radius: 10px;
  padding: 10px 14px;
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease;
}

button:hover {
  transform: translateY(-1px);
}

button.primary {
  background: var(--primary);
  color: white;
}

button.primary:hover {
  background: var(--primary-dark);
}

button.secondary {
  background: #eef2ff;
  color: var(--text);
}

button.danger {
  background: var(--danger-soft);
  color: var(--danger);
}

.toolbar {
  margin-bottom: 16px;
}

.toolbar input,
.toolbar select {
  flex: 1 1 140px;
}

.status {
  color: var(--muted);
  min-height: 24px;
  margin-bottom: 16px;
}

.notes-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.note-card {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
  background: #f8fbff;
}

.note-card h3 {
  margin: 0 0 8px;
}

.note-card p {
  margin: 0 0 10px;
  white-space: pre-wrap;
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.tag {
  border-radius: 999px;
  background: #dbeafe;
  color: #1d4ed8;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 700;
}

.note-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.empty-state {
  border: 1px dashed var(--border);
  border-radius: 12px;
  padding: 30px 20px;
  text-align: center;
  color: var(--muted);
  background: #f8fafc;
}

@media (max-width: 850px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

